def is_good_2_digit(d1, d0):
    m = d1 * 10 + d0
    # Check if removing d1 (d0) results in divisor
    if m % d0 == 0:
        return True
    # Check if removing d0 (d1) results in divisor
    if m % d1 == 0:
        return True
    return False

good_2_digits = []
for d1 in range(1, 10):
    for d0 in range(1, 10):
        if d1 != d0:
            if is_good_2_digit(d1, d0):
                good_2_digits.append(d1 * 10 + d0)

print("Good 2-digit numbers:", sorted(good_2_digits))

m = 9572
digits = [9, 5, 7, 2]
checks = {}

for i in range(4):
    # Create the number m' by removing digits[i]
    m_prime_str = "".join([str(digits[j]) for j in range(4) if j != i])
    m_prime = int(m_prime_str)

    # Check divisibility
    is_divisor = m % m_prime == 0

    checks[m_prime] = {
        "is_divisor": is_divisor,
        "ratio": m / m_prime
    }

print("Divisibility checks for 9572:")
for m_prime, result in checks.items():
    print(f"Removing digit resulting in {m_prime}: Divisor={result['is_divisor']}, Ratio={result['ratio']:.3f}")
